"Agent websites": "Sitios web de los agentes",
"Agent when the app opens": "Agente al abrir la app",
"Agents act through four kinds of steps: run a command, read a file, write a file, or edit part of a file. Before a command runs or a file changes you see exactly what, and choose Run (or Apply), Skip, or Always allow for the rest of the chat. Reading files in the current folder needs no OK.": "Los agentes actúan mediante cuatro tipos de pasos: ejecutar un comando, leer un archivo, escribir un archivo o editar parte de un archivo. Antes de que se ejecute un comando o cambie un archivo, ves exactamente qué se hará y eliges Ejecutar (o Aplicar), Omitir o Permitir siempre durante el resto del chat. Leer archivos de la carpeta actual no requiere tu aprobación.",
"Agents can be wrong. Read what they want to run, especially with Working mode or Root, where a command can remove apps or change settings.": "Los agentes pueden equivocarse. Lee lo que quieren ejecutar, sobre todo con el Modo de operación o con Root, donde un comando puede eliminar apps o cambiar ajustes.",
"Agents only see what you send and what their steps return; keys and tokens in output are hidden from them.": "Los agentes solo ven lo que envías y lo que devuelven sus pasos; las claves y los tokens que aparecen en la salida se les ocultan.",
