"Android and apps then behave as if it was never set. It can be put back from the Undo bar or from Changes.": "Android y las apps se comportarán como si nunca se hubiera definido. Puedes recuperarlo desde la barra Deshacer o desde Cambios.",
"Android asks whether this app may \"Run commands in Termux environment\".": "Android pregunta si esta app puede “Run commands in Termux environment”.",
"Android builds the palette from your home-screen wallpaper (what it does by default).": "Android crea la paleta a partir del fondo de pantalla de inicio (es lo predeterminado).",
