"Android can't verify this APK's signature (edited after signing, or unsigned). It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Android no puede verificar la firma de este APK (editado después de firmarlo o sin firmar). Primero se intenta tal cual; si Android lo rechaza, se instala una copia firmada con la clave de esta app.",
"Android is clearing the caches. This can take up to a minute or two; you can keep using the app.": "Android está borrando las cachés. Puede tardar uno o dos minutos; puedes seguir usando la app.",
