"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Store es un cliente de código abierto de Play Store. La detección automática de versiones de Play está prevista para más adelante (requiere autenticación anónima en Play); por ahora, cada app se dirige a su página en la tienda y se abre Aurora Store si está instalada.",
