"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMind es un servidor MCP: una herramienta que da a los agentes de IA el control de un dispositivo Android mediante ADB (apps, archivos, registros, capturas de pantalla). No es un chat en sí mismo.",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "DroidMind está instalado en Debian. Inícialo con: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Agrégalo a tu agente como servidor MCP (su dirección se muestra al iniciarse).",
