"Freeze, debloat, install, back up and inspect every app on your phone, straight from the phone: through ADB, Wireless Debugging, Shizuku or Root. No computer, no account, no ads.": "Congelar, eliminar bloatware, instalar, hacer copias de seguridad e inspeccionar todas las apps de tu teléfono, directamente desde el teléfono: con ADB, Depuración inalámbrica, Shizuku o Root. Sin computadora, sin cuenta, sin anuncios.",
"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "Desde Gestor de archivos: se instala mediante un backend con privilegios, con las verificaciones de firma de esta app desactivadas. Android sigue verificando las firmas por su cuenta: un APK cuya firma no puede verificar se firma con la clave de esta app y se instala, y una app firmada por otra persona solo se puede reemplazar tras desinstalarla (antes se te pregunta).",
