"GPU load is not exposed the same way on every phone, so this may say \"Not available\" on yours.": "La carga de la GPU no se expone igual en todos los teléfonos, así que en el tuyo puede decir “No disponible”.",
"GRANTED": "CONCEDIDO",
"Galaxy Store": "Galaxy Store",
"Galaxy Store updates for Samsung apps, and open-source updates for sideloaded apps from GitHub, Codeberg, F-Droid, IzzyOnDroid and Obtainium": "Actualizaciones de Galaxy Store para apps de Samsung y actualizaciones de código abierto para apps instaladas manualmente desde GitHub, Codeberg, F-Droid, IzzyOnDroid y Obtainium",
"Game data (OBB)": "Datos del juego (OBB)",
