"Lenovo": "Lenovo",
"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leon es un asistente personal de código abierto (habilidades, voz) que se ejecuta en una computadora con Node.js y Python. No tiene versión para Android y no es un agente de código, así que no chatea en esta Terminal.",
"Leon.ai": "Leon.ai",
"Let Termux take commands from other apps": "Permitir que Termux reciba comandos de otras apps",
"Let them act without asking": "Dejar que actúen sin preguntar",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "Permite que el agente lea y escriba archivos dentro de la carpeta indicada al final del comando (cambia /sdcard a tu gusto).",
"Lets the agent think in explicit steps before it acts.": "Permite que el agente piense en pasos explícitos antes de actuar.",
"Lets this app change a few protected system settings used by some advanced features.": "Permite que esta app cambie algunos ajustes protegidos del sistema que usan ciertas funciones avanzadas.",
"Lets this app install the package files you choose, such as APK, APKS and XAPK files from your storage.": "Permite que esta app instale los archivos de paquete que elijas, como archivos APK, APKS y XAPK de tu almacenamiento.",
"Lets this app open another app's screen from the background, such as an app you have just installed.": "Permite que esta app abra la pantalla de otra app desde segundo plano, por ejemplo una app que acabas de instalar.",
