"Termux could not be opened. Is it installed?": "No se pudo abrir Termux. ¿Está instalado?",
"Termux does not accept commands from other apps yet. In Termux, run:": "Termux aún no acepta comandos de otras apps. En Termux, ejecuta:",
"Termux does not take commands from other apps yet: run the command of step 3 in Termux, then test again.": "Termux todavía no acepta comandos de otras apps: ejecuta el comando del paso 3 en Termux y vuelve a probar.",
"Termux is free. Get it from F-Droid or GitHub; the old Google Play build is not suitable.": "Termux es gratis. Descárgalo de F-Droid o GitHub; la versión antigua de Google Play no sirve.",
