"Termux shells read ~/.bash_profile or ~/.profile first (PATH and the like). Turn off if your profile starts another program.": "Los shells de Termux leen primero ~/.bash_profile o ~/.profile (PATH y similares). Desactívalo si tu perfil inicia otro programa.",
