"That pattern could freeze the list (a repeat inside a repeat, or very long), so it is searched as plain text.": "Ese patrón podría bloquear la lista (una repetición dentro de otra, o muy largo), así que se busca como texto sin formato.",
"That port is used by this phone's own ADB. Use another, like 4444.": "Ese puerto lo usa el ADB propio de este teléfono. Usa otro, como 4444.",
"The # button switches to commands.": "El botón # cambia a comandos.",
"The $ button switches to commands.": "El botón $ cambia a comandos.",
"The ADB key and the APK-signing key are created on this phone and never leave it.": "La clave ADB y la clave de firma de APK se crean en este teléfono y nunca salen de él.",
"The Action Button": "El Botón de acción",
"The Bluetooth link could not be set up.": "No se pudo configurar el enlace Bluetooth.",
"The MCP button opens a sheet to give an agent extra tools (files, the web, a browser, GitHub...) through the Model Context Protocol. Pick a preset or write your own: a name, a local command or a remote address, and any key or header it needs. Pick which agents to add it to — the same server can go into two or more at once, since each agent keeps it in its own file.": "El botón MCP abre una hoja para dar a un agente herramientas adicionales (archivos, la web, un navegador, GitHub...) mediante el Model Context Protocol. Elige un preajuste o escribe el tuyo: un nombre, un comando local o una dirección remota, y la clave o el encabezado que necesite. Elige a qué agentes agregarlo: el mismo servidor puede ir a dos o más a la vez, ya que cada agente lo guarda en su propio archivo.",
"The PDF could not be shown.": "No se pudo mostrar el PDF.",
"The Rish shell ended. Tap Rish mode to open a new one.": "El shell de Rish terminó. Toca Modo Rish para abrir uno nuevo.",
"The Rish shell is no longer running.": "El shell de Rish ya no se está ejecutando.",
"The Terminal needs the app (it is not available in a plain browser)": "La Terminal necesita la app (no está disponible en un navegador normal)",
"The UAD-NG list has not been downloaded yet.": "La lista de UAD-NG aún no se ha descargado.",
"The account has no credit left, or a spending limit was reached.": "La cuenta se quedó sin crédito o se alcanzó un límite de gasto.",
"The agent is still working: STOP it first": "El agente sigue trabajando: toca STOP primero",
"The agent pauses after this many steps.": "El agente hace una pausa tras esta cantidad de pasos.",
"The app is free, and it stays that way. If it saved you time, a coffee helps me keep improving it. Totally optional, and thank you!": "La app es gratis y seguirá siéndolo. Si te ahorró tiempo, un café me ayuda a seguir mejorándola. Es totalmente opcional, ¡y gracias!",
"The archive file is rewritten without this file.": "El archivo comprimido se reescribe sin este archivo.",
"The archive file is rewritten without this folder and everything in it.": "El archivo comprimido se reescribe sin esta carpeta ni nada de lo que contiene.",
"The archive is deleted only when every file of it was extracted, with nothing skipped.": "El archivo comprimido solo se elimina si se extrajeron todos sus archivos, sin omitir ninguno.",
