"The device restarts into the bootloader.": "El dispositivo se reinicia en el bootloader.",
"The device turns off. It has to be started by hand.": "El dispositivo se apaga. Hay que encenderlo a mano.",
"The device's own log.": "El registro propio del dispositivo.",
"The device's system, secure and global settings. A wrong value can make a device misbehave: change one at a time.": "Los ajustes system, secure y global del dispositivo. Un valor incorrecto puede hacer que un dispositivo falle: cambia uno a la vez.",
"The edit could not start": "No se pudo iniciar la edición",
"The extra keys work like Termux's: ESC clears the line, TAB completes a file name, CTRL-C stops what is running, the arrows go through earlier commands and move the cursor, HOME and END jump in the line, and | / - ~ are there because phone keyboards hide them.": "Las teclas adicionales funcionan como las de Termux: ESC borra la línea, TAB completa un nombre de archivo, CTRL-C detiene lo que se está ejecutando, las flechas recorren los comandos anteriores y mueven el cursor, HOME y END saltan dentro de la línea, y | / - ~ están ahí porque los teclados de los teléfonos los ocultan.",
"The extraction could not start": "No se pudo iniciar la extracción",
"The file": "El archivo",
"The file chooser needs the app build": "El selector de archivos necesita la versión de la app",
"The file is removed from this phone's storage, not just from the list. An Undo bar stays for a few seconds, and the file only goes for good once that bar is gone.": "El archivo se elimina del almacenamiento de este teléfono, no solo de la lista. Una barra Deshacer permanece unos segundos y el archivo solo desaparece definitivamente cuando esa barra se va.",
"The fingerprint is shown in the app build": "La huella digital se muestra en la app",
"The folder": "La carpeta",
