"This phone is not connected to its own ADB. Turn on ADB in this app's Working mode first (Working Mode button at the top), then try again.": "Este teléfono no está conectado a su propio ADB. Activa primero ADB en el Modo de operación de esta app (botón Modo de operación, arriba) y vuelve a intentarlo.",
"This phone lists no overlays.": "Este teléfono no muestra ningún overlay.",
